pub fn glyph_for_char(ch: char) -> Option<&'static Glyph> {
    GLYPHS.iter().find(|g| g.ch == ch)
}

pub fn kerning(left: char, right: char) -> i8 {
    match (left, right) {
        ('T', 'e') => -12,
        ('e', 'x') => -3,
        _ => 0,
    }
}
